const http = require('http');
const crypto = require('crypto');
const { URL } = require('url');

const ROLES = { ADMIN: 3, EDITOR: 2, VIEWER: 1 };
const VALID_ROLE_VALUES = new Set(Object.values(ROLES));
const sessions = new Map();
const pendingAuthChecks = new Map();

function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

function hashPassword(password, salt) {
  return crypto.pbkdf2Sync(password, salt, 100000, 64, 'sha512').toString('hex');
}

const users = new Map([
  ['admin', { passwordHash: hashPassword('admin123', 'salt1'), salt: 'salt1', role: ROLES.ADMIN }],
  ['editor', { passwordHash: hashPassword('edit456', 'salt2'), salt: 'salt2', role: ROLES.EDITOR }],
  ['viewer', { passwordHash: hashPassword('view789', 'salt3'), salt: 'salt3', role: ROLES.VIEWER }]
]);

class AuthorizationContext {
  constructor(sessionId, targetPath, requiredRole) {
    this.sessionId = sessionId;
    this.targetPath = targetPath;
    this.requiredRole = requiredRole;
    this.resolvedRole = null;
    this.timestamp = Date.now();
    this.snapshotRole = null;
  }

  captureRole() {
    const session = sessions.get(this.sessionId);
    if (!session) return false;
    this.snapshotRole = session.role;
    return true;
  }

  resolveRole() {
    if (this.snapshotRole === null) return false;
    this.resolvedRole = this.snapshotRole;
    return this.resolvedRole >= this.requiredRole;
  }
}

function getRequiredRole(path) {
  if (path.startsWith('/admin')) return ROLES.ADMIN;
  if (path.startsWith('/edit')) return ROLES.EDITOR;
  if (path.startsWith('/view')) return ROLES.VIEWER;
  return ROLES.VIEWER;
}

function createProxyRequest(targetHost, path, method, headers) {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: targetHost,
      port: 8081,
      path: path,
      method: method,
      headers: { ...headers, 'X-Proxy-Auth': 'verified' }
    };
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve({ status: res.statusCode, body: data }));
    });
    req.on('error', reject);
    req.end();
  });
}

function scheduleAuthCheck(authCtx, callback) {
  const checkId = crypto.randomBytes(8).toString('hex');
  pendingAuthChecks.set(checkId, { ctx: authCtx, cb: callback });

  setImmediate(() => {
    const pending = pendingAuthChecks.get(checkId);
    if (pending) {
      pendingAuthChecks.delete(checkId);
      const authorized = pending.ctx.resolveRole();
      pending.cb(authorized, pending.ctx);
    }
  });

  return checkId;
}

function handleLogin(req, res) {
  let body = '';
  req.on('data', chunk => body += chunk);
  req.on('end', () => {
    try {
      const { username, password } = JSON.parse(body);
      const user = users.get(username);
      if (!user) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid credentials' }));
        return;
      }
      const hash = hashPassword(password, user.salt);
      if (!crypto.timingSafeEqual(Buffer.from(hash), Buffer.from(user.passwordHash))) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid credentials' }));
        return;
      }
      const token = generateToken();
      sessions.set(token, { username, role: user.role, created: Date.now() });
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ token }));
    } catch (e) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Bad request' }));
    }
  });
}

function handleProxyRequest(req, res) {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const targetPath = url.pathname;
  const sessionId = req.headers['x-session-token'];

  if (!sessionId) {
    res.writeHead(401, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'No session token' }));
    return;
  }

  const requiredRole = getRequiredRole(targetPath);
  const authCtx = new AuthorizationContext(sessionId, targetPath, requiredRole);

  if (!authCtx.captureRole()) {
    res.writeHead(401, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Invalid session' }));
    return;
  }

  scheduleAuthCheck(authCtx, (authorized, ctx) => {
    if (!authorized) {
      res.writeHead(403, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Insufficient permissions' }));
      return;
    }

    createProxyRequest('127.0.0.1', ctx.targetPath, req.method, {
      'X-User-Role': String(ctx.resolvedRole),
      'X-Original-Host': req.headers.host || ''
    }).then(result => {
      res.writeHead(result.status, { 'Content-Type': 'application/json' });
      res.end(result.body);
    }).catch(() => {
      res.writeHead(502, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Backend unavailable' }));
    });
  });
}

function handleRoleUpdate(req, res) {
  let body = '';
  req.on('data', chunk => body += chunk);
  req.on('end', () => {
    try {
      const adminToken = req.headers['x-session-token'];
      const adminSession = sessions.get(adminToken);
      if (!adminSession || adminSession.role !== ROLES.ADMIN) {
        res.writeHead(403, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Admin required' }));
        return;
      }
      const { targetToken, newRole } = JSON.parse(body);
      if (typeof newRole !== 'number' || !VALID_ROLE_VALUES.has(newRole)) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid role' }));
        return;
      }
      const targetSession = sessions.get(targetToken);
      if (targetSession) {
        targetSession.role = newRole;
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: true }));
      } else {
        res.writeHead(404, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Session not found' }));
      }
    } catch (e) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Bad request' }));
    }
  });
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);

  if (url.pathname === '/auth/login' && req.method === 'POST') {
    handleLogin(req, res);
  } else if (url.pathname === '/auth/role-update' && req.method === 'POST') {
    handleRoleUpdate(req, res);
  } else {
    handleProxyRequest(req, res);
  }
});

server.listen(8080, () => console.log('Proxy running on :8080'));
